INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷256", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。引文按原文保留，疑似转录讹字单独注明。", "url": "https://github.com/greed-216/histree/blob/fdc81a0b21a4c29dcfb4a4ecc9006df86ffe9248/resources/derived/tongjian/256.txt", "note": "卷256中和四年21段；原始电子文本与SHA-256见来源清单。", "id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "萧遘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：萧遘。", "biography": null, "status": "draft", "id": "4eb0a98d-80ed-52f0-9e2c-2a84e77f2147"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "韦昭度", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：韦昭度。", "biography": null, "status": "draft", "id": "4d186310-6106-56bc-9a34-fa1d5d5d7894"}, {"name": "僧澈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：僧澈。", "biography": null, "status": "draft", "id": "350bc88d-c8b2-5242-821c-181b60786f9e"}, {"name": "知玄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：知玄。", "biography": null, "status": "draft", "id": "9a1fc2aa-7702-51df-8a9f-b502e8dfac45"}, {"name": "严遵美", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：严遵美。", "biography": null, "status": "draft", "id": "ed302757-d39a-520d-9962-a0a86b3c05ce"}, {"name": "孔纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：孔纬。", "biography": null, "status": "draft", "id": "07254f47-15dc-55d0-b38f-bfefa4def94e"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "李鋋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李鋋。", "biography": null, "status": "draft", "id": "0808f476-1fbf-5463-b686-9f85ba9a30f7"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "卢渥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：卢渥。", "biography": null, "status": "draft", "id": "43d3b1d8-b4fe-5c21-a588-fdcc1b281232"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "晋晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：晋晖。", "biography": null, "status": "draft", "id": "60d1489b-54e7-5af8-a534-7ad27c3dfeb2"}, {"name": "张造", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：张造。", "biography": null, "status": "draft", "id": "37eadfba-19d2-5586-9578-12b4a932a89a"}, {"name": "郑君立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郑君立。", "biography": null, "status": "draft", "id": "41c2700f-50cb-5216-9e4d-cc001a758cd5"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "李顺之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李顺之。", "biography": null, "status": "draft", "id": "0e829715-71dc-5592-a62d-e0d5830b7948"}, {"name": "高仁厚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的高仁厚：受任东川留后并领军。", "biography": null, "status": "draft", "id": "ff014a27-d630-52e3-8a2a-fc160fbb8