ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "凤翔百官请诛田令孜及韦昭度", "start_year": 886, "end_year": 886, "time_original": "光启二年三月癸未", "dynasty": "唐", "description": "萧遘等凤翔百官上表列田令孜及其党韦昭度的罪状，请求诛杀二人。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "50b6d33e-d18a-5163-9395-6e6ebb64e3b9"}, {"title": "韦昭度此前经僧澈结识宦官而为相", "start_year": null, "end_year": null, "time_original": "“初”追叙；确年待考", "dynasty": "唐", "description": "《通鉴》追叙韦昭度经供奉僧澈结交宦官而获相位；其师知玄不赞同僧澈的行为。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0ed0d349-18cf-5adc-8054-65064d9c137b"}, {"title": "车驾抵达兴元", "start_year": 886, "end_year": 886, "time_original": "光启二年三月丙申", "dynasty": "唐", "description": "山南西道监军严遵美在西县迎接皇帝，丙申车驾抵达兴元。", "phases": [], "location_name": "西县、兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87315bed-349b-5df6-88f1-795170ec2b2e"}, {"title": "孔纬、杜让能获任同平章事", "start_year": 886, "end_year": 886, "time_original": "光启二年三月戊戌", "dynasty": "唐", "description": "朝廷以孔纬、杜让能并为兵部侍郎、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "41109c0d-fe4c-5bad-86e8-7428c8c7d11f"}, {"title": "李鋋等在凤州击败邠军", "start_year": 886, "end_year": 886, "time_original": "光启二年三月条；具体日未载", "dynasty": "唐", "description": "保銮都将李鋋等在凤州击败邠军。", "phases": [], "location_name": "凤州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2fa4c6a1-4cce-5635-9fbd-12acd28e145b"}, {"title": "朝廷命王重荣调粮，王重荣拒奉诏", "start_year": 886, "end_year": 886, "time_original": "光启二年三月条；具体日未载", "dynasty": "唐", "description": "朝廷加王重荣应接粮料使，令从本道调谷十五万斛供国用；王重荣上表称田令孜未被诛，拒绝奉诏。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ff6b26da-d789-57e4-ba3e-a015deb59a3b"}, {"title": "卢渥任山南西道留后", "start_year": 886, "end_year": 886, "time_original": "光启二年三月条；具体日未载", "dynasty": "唐", "description": "朝廷任尚书左丞卢渥为户部尚书，并充山南西道留后。", "phases": [], "location_name": "山南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9535ebdb-6c0c-5010-ad59-6149cb9feccd"}, {"title": "严遵美任内枢密使", "start_year": 886, "end_year": 886, "time_original": "光启二年三月条；具体日未载", "dynasty": "唐", "description": "朝廷任严遵美为内枢密使。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "5ae5ae78-e30e-5ccb-a4a7-4136dab63b17"}, {"title": "王建守三泉，晋晖、张造屯黑水修栈道", "start_year": 886, "end_year": 886, "time_original": "光启二年三月条；具体日未载", "dynasty": "唐", "description": "朝廷派王建率部守三泉、晋晖与张造率四都兵屯黑水，修栈道以通往来；王建遥领壁州刺史。", "phases": [], "location_name": "三泉、黑水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5db95cf9-a0d7-5c10-8e4d-d0f9b89b5517"}, {"title": "郑君立攻陷汉州后战败身死", "start_year": 886, "end_year": 886, "time_original": "光启二年三月后条；具体日未载", "dynasty": "唐", "description": "郑君立自遂州起兵，攻陷汉州、进向成都；陈敬瑄派李顺之迎战，郑君立战败身死。", "phases": [], "location_name": "汉州、成都方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "427ca027-285d-5bf2-9cb9-516fb33c9357"}, {"title": "陈敬瑄派维、茂羌军杀高仁厚", "start_year": 886, "end_year": 886, "time_original": "郑君立之乱后；具体日未载", "dynasty": "唐", "description": "陈敬瑄猜疑东川节度使高仁厚，发维、茂羌军攻之，高仁厚被杀。", "phases": [], "location_name": "东川方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ef2049dc-434a-5ae9-bbde-cf7359ff2839"}, {"title": "朱玫劝萧遘改立李氏宗室，萧遘拒绝", "start_year": 886, "end_year": 886, "time_original": "光启二年春；具体日未载", "dynasty": "唐", "description": "朱玫与萧遘谈及皇帝受田令孜控制，提出改立李氏宗室。萧遘认为罪在田令孜，不愿参与废立；朱玫随后公开声称要拥立一名李氏王。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "0903438c-449f-54ed-9971-07f03c19b1c0"}, {"title": "朱玫迫凤翔百官奉襄王煴监国", "start_year": 886, "end_year": 886, "time_original": "光启二年夏四月壬子", "dynasty": "唐", "description": "朱玫迫凤翔百官奉襄王煴权监军国事，令其承制封拜，并在石鼻驿使百官盟誓。", "phases": [], "location_name": "凤翔、石鼻驿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d471f3b4-5197-5aca-8541-764faa59b7da"}, {"title": "襄王煴受册，朱玫率百官奉之还京", "start_year": 886, "end_year": 886, "time_original": "光启二年夏四月乙卯", "dynasty": "唐", "description": "萧遘辞撰册文，郑昌图代撰。乙卯襄王煴受册；朱玫自兼左右神策十军使，率百官奉煴返回京师。", "phases": [], "location_name": "凤翔、京师方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2549d876-fa9d-52b8-bcb6-3a0b5fb82494"}, {"title": "郑昌图获任同平章事并掌三司", "start_year": 886, "end_year": 886, "time_original": "光启二年夏四月乙卯后", "dynasty": "唐", "description": "朱玫一方任郑昌图同平章事、判度支盐铁户部，使其掌三司事务。河中百官崔安潜等上笺祝贺襄王煴受册。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7383e0ed-dba4-563a-86cf-d6ec84cd3fa3"}, {"title": "田令孜荐杨复恭继任，自往依陈敬瑄", "start_year": 886, "end_year": 886, "time_original": "光启二年夏四月后条；具体日未载", "dynasty": "唐", "description": "田令孜荐杨复恭任左神策中尉、观军容使，自除西川监军使，离开行在去依附陈敬瑄。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "85ff4316-7d02-5322-8eee-211c6c0b8341"}, {"title": "杨复恭出任王建等四人为外州刺史", "start_year": 886, "end_year": 886, "time_original": "田令孜离开后；具体日未载", "dynasty": "唐", "description": "杨复恭排斥田令孜党人，任王建为利州刺史、晋晖为集州刺史、张造为万州刺史、李师泰为忠州刺史。", "phases": [], "location_name": "利州、集州、万州、忠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b2124154-3ba6-5312-986b-ba1c51bf3ebc"}]'::jsonb)
